package com.hellodoc.service;
import com.hellodoc.dto.*; import com.hellodoc.entity.*; import com.hellodoc.repository.*; import org.springframework.context.ApplicationEventPublisher; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.util.UUID;
@Service public class DoctorApprovalService {
 private final DoctorApplicationRepository applications; private final UserRepository users; private final DoctorProfileService profiles; private final ApplicationEventPublisher events; private final AdministrativeAuditService audit;
 public DoctorApprovalService(DoctorApplicationRepository applications,UserRepository users,DoctorProfileService profiles,ApplicationEventPublisher events,AdministrativeAuditService audit){this.applications=applications;this.users=users;this.profiles=profiles;this.events=events;this.audit=audit;}
 @org.springframework.beans.factory.annotation.Value("${hellodoc.email.enabled:false}") private boolean emailEnabled;
 @Transactional public DoctorApplicationSummary approve(UUID id,DecisionRequest request){DoctorApplication a=locked(id);if("APPROVED".equals(a.getStatus()))return DoctorApplicationSummary.from(a);requirePending(a);if(!a.hasDoctorDocument())throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"L’attestation d’inscription à l’Ordre est obligatoire pour approuver cette candidature.");profiles.createFromApplication(a);a.decide("APPROVED",request==null?null:request.reason());a.getUser().setRoleAndStatus(UserRole.DOCTOR,"ACTIVE");a.queueApprovalEmail(emailEnabled);users.save(a.getUser());audit.record("DOCTOR_APPROVED","DOCTOR_APPLICATION",a.getId());events.publishEvent(new DoctorApplicationApprovedEvent(a.getId(),a.getUser().getEmail(),a.getUser().getFirstName(),a.getUser().getLastName()));return DoctorApplicationSummary.from(a);}
 @Transactional public DoctorApplicationSummary reject(UUID id,DecisionRequest request){if(request.reason()==null||request.reason().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A reason is required to reject a doctor application.");DoctorApplication a=pending(id);a.decide("REJECTED",request.reason().trim());a.getUser().setRoleAndStatus(UserRole.USER,"REJECTED");audit.record("DOCTOR_REJECTED","DOCTOR_APPLICATION",a.getId());return DoctorApplicationSummary.from(a);}
 private DoctorApplication locked(UUID id){return applications.findByIdForUpdate(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Candidature introuvable."));}
 private void requirePending(DoctorApplication a){if(!"PENDING".equals(a.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Cette candidature a déjà fait l’objet d’une décision.");}
 private DoctorApplication pending(UUID id){DoctorApplication a=locked(id);requirePending(a);return a;}
}
